"test_acceptance.js": "const fs = require('fs');
const path = require('path');

const files = ['index.html', 'styles.css', 'script.js', 'README.md'];
let pass = true;
const results = [];

// 1. Check files exist
for (const f of files) {
  if (!fs.existsSync(f)) {
    results.push(`FAIL: ${f} missing`);
    pass = false;
  }
}

if (pass) {
  const html = fs.readFileSync('index.html', 'utf8');

  // 2. Hero text
  if (!html.includes('Explorá con calma')) {
    results.push('FAIL: Hero text missing');
    pass = false;
  }

  // 3. CTA link
  if (!html.includes('Ver planes') || !html.includes('#planes')) {
    results.push('FAIL: CTA Ver planes #planes missing');
    pass = false;
  }

  // 4. Nav links
  const navLinks = ['#beneficios', '#planes', '#preguntas', '#contacto'];
  for (const link of navLinks) {
    if (!html.includes(link)) {
      results.push(`FAIL: Nav link ${link} missing`);
      pass = false;
    }
  }
  if (!html.includes('Saltar al contenido')) {
    results.push('FAIL: Skip to content link missing');
    pass = false;
  }

  // 5. Benefits section
  if (!html.includes('#beneficios') || !html.includes('beneficios')) {
    results.push('FAIL: Benefits section structure issue');
    pass = false;
  }

  // 6. Plans section
  if (!html.includes('#planes')) {
    results.push('FAIL: Plans section missing');
    pass = false;
  }
  if (!html.includes('ejemplo')) {
    results.push('FAIL: Plans example price marker missing');
    pass = false;
  }

  // 7. FAQ section
  if (!html.includes('#preguntas')) {
    results.push('FAIL: FAQ section missing');
    pass = false;
  }
  if (!html.includes('<details') && !html.includes('aria-expanded')) {
    results.push('FAIL: FAQ accessible structure missing');
    pass = false;
  }

  // 8. Form validation
  if (!html.includes('<form') || !html.includes('name') || !html.includes('email') || !html.includes('message')) {
    results.push('FAIL: Contact form fields missing');
    pass = false;
  }
  if (!html.includes('label') && !html.includes('aria-label')) {
    results.push('FAIL: Form labels missing');
    pass = false;
  }

  // 9. SEO
  if (!html.includes('<title') || !html.includes('meta name="description"') || !html.includes('viewport')) {
    results.push('FAIL: SEO meta tags missing');
    pass = false;
  }
  if (!html.includes('lang="es"')) {
    results.push('FAIL: HTML lang es missing');
    pass = false;
  }

  // 10. CSS checks
  const css = fs.readFileSync('styles.css', 'utf8');
  if (!css.includes('prefers-reduced-motion')) {
    results.push('FAIL: prefers-reduced-motion media query missing');
    pass = false;
  }
  if (!css.includes('@media') || !css.includes('768px') || !css.includes('1440px')) {
    results.push('FAIL: Responsive breakpoints missing');
    pass = false;
  }

  // 11. README checks
  const readme = fs.readFileSync('README.md', 'utf8');
  const specialChars = 'áéíóú ñ ¿? € ° "comillas"';
  for (const char of specialChars.split(' ')) {
    if (!readme.includes(char)) {
      results.push(`FAIL: README missing character: ${char}`);
      pass = false;
    }
  }

  // 12. JS checks
  const js = fs.readFileSync('script.js', 'utf8');
  if (js.includes('fetch(') || js.includes('XMLHttpRequest')) {
    results.push('FAIL: Network calls found in JS');
    pass = false;
  }
  if (js.includes('console.log(') === false && js.includes('function') === false && js.includes('addEventListener') === false) {
     // Basic functionality check, not exhaustive
  }
}

if (pass) {
  console.log('ACCEPTANCE_PASS');
} else {
  console.error('ACCEPTANCE_FAIL');
  results.forEach(r => console.error(r));
  process.exit(1);
}",
"build_check.js": "const fs = require('fs');
const path = require('path');

// Verify syntax of script.js using Node's built-in parser
try {
  const jsContent = fs.readFileSync('script.js', 'utf8');
  new Function(jsContent); // Basic syntax check
} catch (e) {
  console.error(`FAIL: script.js syntax error: ${e.message}`);
  process.exit(1);
}

// Verify HTML structure is valid enough for basic parsing
try {
  const htmlContent = fs.readFileSync('index.html', 'utf8');
  if (!htmlContent.includes('<html') || !htmlContent.includes('</html>')) {
    throw new Error('HTML structure incomplete');
  }
} catch (e) {
  console.error(`FAIL: index.html structure error: ${e.message}`);
  process.exit(1);
}

// Verify CSS file is readable and non-empty
try {
  const cssContent = fs.readFileSync('styles.css', 'utf8');
  if (cssContent.length === 0) {
    throw new Error('styles.css is empty');
  }
} catch (e) {
  console.error(`FAIL: styles.css error: ${e.message}`);
  process.exit(1);
}

console.log('BUILD_PASS');
"
